'use strict';

const crypto = require('crypto');


/* ============================================================
   DIRAC UNIVERSAL DEPLOYMENT ROOT v250
   One health.js for every Dirac role. Domain/provider identity is ENV-driven.
   ============================================================ */
const DIRAC_UNIVERSAL_APP_ROLES_V250 = Object.freeze(new Set([
  'www', 'auth', 'dashboard', 'security', 'parfum', 'pesanan', 'recovery'
]));

function diracBaseDomainV250() {
  const configured = String(process.env.DIRAC_BASE_DOMAIN || '').trim();
  if (!configured && process.env.NODE_ENV === 'production') throw new Error('DIRAC_BASE_DOMAIN_REQUIRED');
  const raw = String(configured || 'example.invalid').toLowerCase().replace(/^https?:\/\//, '').replace(/\/$/, '').replace(/^\./, '');
  if (!raw || raw.length > 253 || raw.includes('/') || raw.includes(':') || !/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(raw)) {
    throw new Error('DIRAC_BASE_DOMAIN_INVALID');
  }
  return raw;
}

function diracAppRoleV250() {
  const role = String(process.env.DIRAC_APP_ROLE || '').trim().toLowerCase();
  if (DIRAC_UNIVERSAL_APP_ROLES_V250.has(role)) return role;
  if (process.env.NODE_ENV === 'production') throw new Error('DIRAC_APP_ROLE_INVALID');
  return 'www';
}

function diracS2SServerIdV250() {
  return String(process.env.DIRAC_S2S_SERVER_ID || '').trim().toLowerCase();
}

function diracRoleHostnameV250(role) {
  const clean = String(role || '').trim().toLowerCase();
  if (!DIRAC_UNIVERSAL_APP_ROLES_V250.has(clean)) throw new Error('DIRAC_TARGET_ROLE_INVALID');
  return (clean === 'recovery' ? 'secure' : clean) + '.' + diracBaseDomainV250();
}

function diracRoleOriginV250(role) {
  return 'https://' + diracRoleHostnameV250(role);
}

function diracBaseOriginV250() {
  return 'https://' + diracBaseDomainV250();
}

function diracLocalOriginV250() {
  return diracRoleOriginV250(diracAppRoleV250());
}

function diracRoleApiUrlV250(role, action) {
  const cleanAction = String(action || '').trim().toLowerCase();
  if (!/^[a-z0-9_]{1,80}$/.test(cleanAction)) throw new Error('DIRAC_TARGET_ACTION_INVALID');
  const url = new URL('/api/health', diracRoleOriginV250(role));
  url.searchParams.set('action', cleanAction);
  return url.toString();
}

function diracRoleFromHostnameV250(hostname) {
  const host = String(hostname || '').trim().toLowerCase().replace(/\.$/, '');
  const suffix = '.' + diracBaseDomainV250();
  if (!host.endsWith(suffix)) return '';
  const role = host.slice(0, -suffix.length);
  return DIRAC_UNIVERSAL_APP_ROLES_V250.has(role) ? role : '';
}

function diracUniversalBrowserOriginsV250() {
  const origins = new Set([diracBaseOriginV250(), diracLocalOriginV250()]);
  const add = (value) => {
    try {
      const raw = String(value || '').trim();
      if (!raw) return;
      const u = new URL(raw.includes('://') ? raw : 'https://' + raw);
      if (u.protocol === 'https:' || (process.env.NODE_ENV !== 'production' && u.protocol === 'http:')) origins.add(u.origin.toLowerCase());
    } catch (_) {}
  };
  for (const role of DIRAC_UNIVERSAL_APP_ROLES_V250) add(diracRoleOriginV250(role));
  for (const item of ('api,panel,website,cs,' + String(process.env.DIRAC_OFFICIAL_SUBDOMAINS || '')).split(',')) {
    const subdomain = String(item || '').trim().toLowerCase().replace(/^\.+|\.+$/g, '');
    if (!subdomain) continue;
    if (!/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$/.test(subdomain)) {
      if (process.env.NODE_ENV === 'production') throw new Error('DIRAC_OFFICIAL_SUBDOMAIN_INVALID');
      continue;
    }
    add('https://' + subdomain + '.' + diracBaseDomainV250());
  }
  add(process.env.DOMAIN_SITE_URL);
  add(process.env.SITE_URL);
  return origins;
}

function diracSupportEmailV250() {
  const explicit = String(process.env.DIRAC_SUPPORT_EMAIL || '').trim();
  return explicit || ('support@' + diracBaseDomainV250());
}

function diracUniversalRecoveryPrivateEnvNamesV250() {
  return [
    'DIRAC_RECOVERY_WORKER_X25519_PRIVATE_KEY',
    'DIRAC_RECOVERY_WORKER_MLKEM1024_PRIVATE_KEY',
    'DIRAC_RECOVERY_HPKE_PRIVATE_KEY',
    'DIRAC_RECOVERY_MLKEM1024_PRIVATE_KEY_PEM',
    'DIRAC_RECOVERY_MLKEM1024_PRIVATE_KEY_DER_B64',
    'DIRAC_RECOVERY_MLDSA87_PRIVATE_KEY_PEM',
    'DIRAC_RECOVERY_MLDSA87_PRIVATE_KEY_DER_B64',
    'DIRAC_LOST_PASSKEY_ED25519_PRIVATE_KEY',
    'DIRAC_LOST_PASSKEY_ED25519_PRIVATE_KEY_PEM'
  ];
}

function diracAssertUniversalDeploymentConfigV250() {
  const role = diracAppRoleV250();
  const serverId = diracS2SServerIdV250();
  if (!serverId || serverId !== role) throw new Error('DIRAC_APP_ROLE_S2S_SERVER_ID_MISMATCH');
  if (String(process.env.DOMAIN_COOKIE_DOMAIN || '').trim()) throw new Error('DOMAIN_COOKIE_DOMAIN_MUST_BE_UNSET_FOR_HOST_ONLY_COOKIES');
  if (role !== 'recovery' && diracUniversalRecoveryPrivateEnvNamesV250().some((name) => String(process.env[name] || '').trim())) {
    throw new Error('DIRAC_RECOVERY_PRIVATE_ENV_OUTSIDE_RECOVERY_ROLE');
  }
  return true;
}

if (process.env.NODE_ENV === 'production') diracAssertUniversalDeploymentConfigV250();

/* ============================================================
   DIRAC CENTRAL ARCHITECTURE CONSOLIDATION v202
   Flat middleware registry. A single final export is installed at EOF.
   Existing business-handler bodies remain unchanged.
   ============================================================ */
const DIRAC_CENTRAL_ARCHITECTURE_CONSOLIDATION_V202 = 'dirac-central-architecture-consolidation-v202';
const __diracV202MiddlewareRegistry = [];
const __diracV202WrapperFlags = new Set();
let __diracV202MiddlewareRegistryLockedV228 = false;
function __diracV202DispatcherSentinel() {}
function __diracV202RegisterMiddleware(fn, name) {
  if (__diracV202MiddlewareRegistryLockedV228) throw new Error('DIRAC_V202_MIDDLEWARE_REGISTRY_LOCKED');
  if (typeof fn !== 'function') throw new Error('DIRAC_V202_MIDDLEWARE_INVALID');
  __diracV202MiddlewareRegistry.push(Object.freeze({ fn, name: String(name || fn.name || 'anonymous') }));
  return fn;
}
function __diracV202MarkWrapperFlag(name) {
  const clean = String(name || '');
  if (!clean) return false;
  __diracV202WrapperFlags.add(clean);
  try { Object.defineProperty(__diracV202DispatcherSentinel, clean, { value: true, enumerable: false, configurable: false }); } catch (_) {}
  return true;
}

const DIRAC_MIDTRANS_DEBUG_PATCH = 'midtrans-dashboard-key-accept-v11';
const DIRAC_IPAYMU_PATCH = 'ipaymu-redirect-v12';
const DIRAC_COOKIE_SESSION_PATCH = 'cookie-signed-session-v16';

const DEFAULT_ALLOWED_ORIGINS = Array.from(diracUniversalBrowserOriginsV250());

const DOMAIN_ACTIONS = new Set([
  'domain_health',
  'hostinger_check',
  'domain_login',
  'domain_register',
  'domain_me',
  'domain_dashboard_me',
  'domain_logout',
  'domain_check',
  'domain_checkout',
  'domain_orders',
  'domain_mfa_status'
]);

const DOMAIN_ACTION_ALIASES = Object.freeze({
  'domain-health': 'domain_health',
  'domain_health': 'domain_health',
  'hostinger-check': 'hostinger_check',
  'hostinger_check': 'hostinger_check',
  'hostinger-domain-check': 'hostinger_check',
  'domain_hostinger_check': 'hostinger_check',
  'check-domain': 'domain_check',
  'domain_check': 'domain_check',
  'create-order': 'domain_checkout',
  'domain_create_order': 'domain_checkout',
  'get-orders': 'domain_orders',
  'domain_get_orders': 'domain_orders',
  'domain-login': 'domain_login',
  'domain_login': 'domain_login',
  'login-domain': 'domain_login',
  'domain-register': 'domain_register',
  'domain_register': 'domain_register',
  'register-domain': 'domain_register',
  'domain-me': 'domain_me',
  'domain-dashboard-me': 'domain_dashboard_me',
  'domain_dashboard_me': 'domain_dashboard_me',
  'dashboard-me': 'domain_dashboard_me',
  'dashboard_me': 'domain_dashboard_me',
  'dashboard-summary': 'domain_dashboard_me',
  'dashboard_summary': 'domain_dashboard_me',
  'domain_logout': 'domain_logout',
  'domain-logout': 'domain_logout',
  'domain-mfa-status': 'domain_mfa_status',
  'domain_mfa_status': 'domain_mfa_status',
  'dashboard-mfa-status': 'domain_mfa_status'
});

const __diracV202BaseHandler = async function handler(req, res) {
  const rawAction = String((req.query && req.query.action) || '').trim();
  const action = normalizeDomainAction(rawAction);
  const isDomainAction = DOMAIN_ACTIONS.has(action);
  const isLegacyAuthPost = !rawAction && (req.method === 'POST' || req.method === 'OPTIONS');

  const cors = setCors(req, res, { isDomainAction: isDomainAction || isLegacyAuthPost });
  if (req.method === 'OPTIONS') return res.status(cors.allowed ? 200 : 403).end();
  if (!cors.allowed) return res.status(403).json({ ok: false, message: 'Origin tidak diizinkan.' });

  if (isDomainAction) {
    return handleDomainAction(action, req, res);
  }

  if (isLegacyAuthPost) {
    let legacyBody;
    try {
      legacyBody = await readLimitedJsonBody(req, LOGIN_SECURITY_BODY_LIMIT_BYTES);
    } catch (error) {
      return res.status(error.statusCode || 400).json({
        ok: false,
        code: error.code || 'LOGIN_REQUEST_INVALID',
        message: error.publicMessage || 'Request login tidak valid.'
      });
    }
    const legacyMode = String(legacyBody.mode || legacyBody.action || '').trim().toLowerCase();
    if (legacyMode === 'login' || legacyMode === 'domain_login') return domainLogin(req, res, legacyBody);
    if (legacyMode === 'register' || legacyMode === 'signup' || legacyMode === 'domain_register') return domainRegister(req, res, legacyBody);
    return res.status(400).json({ ok: false, message: 'Mode autentikasi tidak valid.' });
  }

  if (req.method !== 'GET') return res.status(405).json({ ok: false, message: 'Method tidak diizinkan.' });

  const payload = {
    ok: true,
    service: 'dirac-ai',
    chatEndpoint: '/api/chat',
    time: diracNowIso()
  };

  if (isAdminRequest(req) || allowPublicHealthDetails(req)) {
    payload.providers = {
      gemini: Boolean(process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEYS || process.env.GEMINI_API_KEY_1),
      groq: Boolean(process.env.GROQ_API_KEY || process.env.GROQ_API_KEYS || process.env.GROQ_API_KEY_1),
      openai: Boolean(process.env.OPENAI_API_KEY || process.env.OPENAI_API_KEYS || process.env.OPENAI_API_KEY_1)
    };
    payload.siteUrl = process.env.SITE_URL || diracLocalOriginV250();
  }

  return res.status(200).json(payload);
};

function setCors(req, res, options = {}) {
  const allowed = new Set(getAllowedOrigins());
  const origin = req.headers && req.headers.origin;
  const noOrigin = !origin;
  const allowedOrigin = origin && allowed.has(origin) ? origin : '';
  if (allowedOrigin) res.setHeader('Access-Control-Allow-Origin', allowedOrigin);
  res.setHeader('Vary', 'Origin');
  res.setHeader('Access-Control-Allow-Methods', options.isDomainAction ? 'GET, HEAD, POST, OPTIONS' : 'GET, HEAD, OPTIONS');

  const domainAllowedHeaders = [
    'Content-Type',
    'Accept',
    'Idempotency-Key',
    'X-Idempotency-Key',
    'X-CSRF-Token',
    'X-Dirac-CSRF-Token',
    'X-Dirac-Page-Nonce',
    'X-Page-Nonce',
    'X-Dirac-Public-Nonce',
    'X-Dirac-A2F-Ticket',
    'X-Dirac-A2F-Signature',
    'X-Dirac-A2F-Timestamp',
    'X-Dirac-A2F-Nonce',
    'X-Requested-With',
    'content-type',
    'accept',
    'idempotency-key',
    'x-idempotency-key',
    'x-csrf-token',
    'x-dirac-csrf-token',
    'x-dirac-page-nonce',
    'x-page-nonce',
    'x-dirac-public-nonce',
    'x-dirac-a2f-ticket',
    'x-dirac-a2f-signature',
    'x-dirac-a2f-timestamp',
    'x-dirac-a2f-nonce',
    'x-requested-with'
  ];

  if (options.isDomainAction && String(req && req.query && req.query.action || '').trim() === 'domain_health') {
    domainAllowedHeaders.push('X-Dirac-CSRF-Probe', 'x-dirac-csrf-probe');
  }

  // PATCH 3A: backend-only customer auth.
  // Frontend/customer HTML tidak lagi dipercaya membawa Authorization, refresh token,
  // atau MFA proof lewat header. Browser hanya mengirim HttpOnly Secure cookie otomatis.
  if (options.isDomainAction && shouldAcceptFrontendAuthHeaders()) {
    domainAllowedHeaders.push(
      'Authorization',
      'X-Supabase-Access-Token',
      'X-Domain-Access-Token',
      'X-Dirac-Access-Token',
      'X-Firebase-ID-Token',
      'X-Admin-Auth-Provider',
      'X-Dirac-Admin',
      'X-Domain-Refresh',
      'X-Refresh-Token',
      'X-Dirac-MFA-Proof',
      'X-Dashboard-MFA-Proof',
      'X-Dirac-Dashboard-MFA',
      'authorization',
      'x-domain-refresh',
      'x-refresh-token',
      'x-dirac-mfa-proof',
      'x-dashboard-mfa-proof',
      'x-dirac-dashboard-mfa'
    );
  }

  res.setHeader(
    'Access-Control-Allow-Headers',
    options.isDomainAction
      ? domainAllowedHeaders.join(', ')
      : 'Content-Type, X-Dirac-Admin, content-type, x-dirac-admin'
  );
  if (options.isDomainAction) {
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    const exposedHeaders = ['X-Domain-Token-Refreshed', 'Retry-After', 'X-Dirac-Page-Nonce', ...(String(req && req.query && req.query.action || '').trim() === 'domain_health' ? ['X-Dirac-A2F-Ticket', 'X-Dirac-A2F-Signature', 'X-Dirac-A2F-Timestamp', 'X-Dirac-A2F-Nonce'] : [])];
    if (!shouldHideDomainAuthTokens()) {
      exposedHeaders.unshift('X-Domain-Access-Token', 'X-Domain-Refresh-Token');
    }
    res.setHeader('Access-Control-Expose-Headers', exposedHeaders.join(', '));
  }
  res.setHeader('Access-Control-Max-Age', '600');
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  return { allowed: noOrigin || !!allowedOrigin };
}

function getAllowedOrigins() {
  const fromEnv = String(process.env.AI_ALLOWED_ORIGINS || '').split(',').map((item) => item.trim()).filter(Boolean);
  const domainSite = String(process.env.DOMAIN_SITE_URL || '').trim();
  const dev = process.env.NODE_ENV !== 'production' ? ['http://localhost:3000', 'http://127.0.0.1:3000', 'http://localhost:5173', 'http://127.0.0.1:5173'] : [];
  return Array.from(new Set([...DEFAULT_ALLOWED_ORIGINS, domainSite, ...fromEnv, ...dev].filter(Boolean)));
}

function isAdminRequest(req) {
  const secret = String(process.env.AI_ADMIN_SECRET || '');
  const candidate = String(req && req.headers && req.headers['x-dirac-admin'] || '');
  if (!secret || !candidate) return false;
  const expected = crypto.createHash('sha512').update(secret, 'utf8').digest();
  const received = crypto.createHash('sha512').update(candidate, 'utf8').digest();
  return Buffer.byteLength(candidate, 'utf8') === Buffer.byteLength(secret, 'utf8')
    && crypto.timingSafeEqual(received, expected);
}

function normalizeDomainAction(action) {
  const cleanAction = String(action || '').trim();
  return DOMAIN_ACTION_ALIASES[cleanAction] || cleanAction;
}

