    ok: byteLength >= 12 && byteLength <= 32,
    pdfPassword,
    byteLength,
    maxBytes: 32,
    accountPasswordMaxBytes: Math.max(0, 32 - Buffer.byteLength(String(websiteRecoveryCode || '').trim() + String(emailPdfCode || '').trim(), 'utf8'))
