  return res.status(200).json({
    ok: result.ok === true,
    login_history_limit: 8,
    pruned: Number(result.pruned || 0),
    message: result.ok ? 'Riwayat login lama dibersihkan. Maksimal 8 data terbaru disimpan.' : 'Riwayat login belum bisa dibersihkan.',
    time: diracNowIso()
  });
